def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import deque

    def apply_absorption(expr1, expr2):
        if isinstance(expr1, tuple) and isinstance(expr2, tuple):
            op1, a1, b1 = expr1
            op2, a2, b2 = expr2
            if op1 == '&' and op2 == '|':
                if a1 == a2:
                    return a1
                if a1 == ('~', a2):
                    return ('&', a1, b2)
            if op1 == '|' and op2 == '&':
                if a1 == a2:
                    return a1
                if a1 == ('~', a2):
                    return ('|', a1, b2)
        return None

    queue = deque(args)
    result = []

    while queue:
        expr1 = queue.popleft()
        if queue:
            expr2 = queue.popleft()
            absorbed_expr = apply_absorption(expr1, expr2)
            if absorbed_expr:
                queue.appendleft(absorbed_expr)
            else:
                result.append(expr1)
                queue.appendleft(expr2)
        else:
            result.append(expr1)

    return result
