                if overrides:
                    config.read_dict(overrides)
                config_dict[config_filename] = config
        except (configparser.Error, FileNotFoundError, IOError) as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(record)

